CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS project_meta (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, schema_version INTEGER NOT NULL, creative_rules TEXT NOT NULL DEFAULT '', last_backup_at INTEGER, search_revision INTEGER NOT NULL DEFAULT 0 CHECK(search_revision >= 0), indexed_revision INTEGER NOT NULL DEFAULT 0 CHECK(indexed_revision >= 0), search_index_error TEXT);
CREATE TABLE IF NOT EXISTS chapter (id TEXT PRIMARY KEY, title TEXT NOT NULL, position INTEGER NOT NULL, content TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL CHECK(version >= 1), deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uidx_chapter_position_active ON chapter(position) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS chapter_snapshot (id TEXT PRIMARY KEY, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE CASCADE, chapter_version INTEGER NOT NULL, title TEXT NOT NULL, name TEXT, content TEXT NOT NULL, snapshot_kind TEXT NOT NULL CHECK(snapshot_kind IN ('ordinary','ai_apply','split','merge','restore','manual')), permanent INTEGER NOT NULL CHECK(permanent IN (0,1)), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS style_sample (id TEXT PRIMARY KEY, name TEXT NOT NULL, content TEXT NOT NULL, tags_json TEXT NOT NULL DEFAULT '[]', version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS instruction_preset (id TEXT PRIMARY KEY, task_type TEXT NOT NULL CHECK(task_type IN ('chat','knowledge','report','continue','rewrite','polish')), name TEXT NOT NULL, instruction TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS task_route (id TEXT PRIMARY KEY, task_type TEXT NOT NULL UNIQUE CHECK(task_type IN ('chat','knowledge','report','continue','rewrite','polish')), connection_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 1), updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_entry (id TEXT PRIMARY KEY, knowledge_kind TEXT NOT NULL CHECK(knowledge_kind IN ('character','world','timeline','foreshadow')), title TEXT NOT NULL, aliases_json TEXT NOT NULL DEFAULT '[]', author_content TEXT NOT NULL DEFAULT '', tags_json TEXT NOT NULL DEFAULT '[]', identity TEXT, current_state TEXT, narrative_order INTEGER, story_time TEXT, relative_time TEXT, time_uncertain INTEGER CHECK(time_uncertain IN (0,1)), foreshadow_state TEXT, version INTEGER NOT NULL CHECK(version >= 1), state TEXT NOT NULL CHECK(state IN ('active','archived')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS character_relationship (id TEXT PRIMARY KEY, from_character_id TEXT NOT NULL REFERENCES knowledge_entry(id) ON DELETE RESTRICT, to_character_id TEXT NOT NULL REFERENCES knowledge_entry(id) ON DELETE RESTRICT, relation_type TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, CHECK(from_character_id <> to_character_id));
CREATE TABLE IF NOT EXISTS task (id TEXT PRIMARY KEY, type TEXT NOT NULL, scope_json TEXT NOT NULL, connection_id TEXT, state TEXT NOT NULL CHECK(state IN ('queued','running','completed','cancelled','failed','interrupted')), cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)), input_tokens INTEGER, output_tokens INTEGER, error_code TEXT, error_message TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, started_at INTEGER, completed_at INTEGER);
CREATE TABLE IF NOT EXISTS ai_fact_suggestion (id TEXT PRIMARY KEY, knowledge_entry_id TEXT REFERENCES knowledge_entry(id) ON DELETE SET NULL, knowledge_kind TEXT NOT NULL CHECK(knowledge_kind IN ('character','world','timeline','foreshadow')), normalized_subject TEXT NOT NULL, predicate TEXT NOT NULL, value_json TEXT NOT NULL, display_text TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','accepted','ignored','conflict')), confidence REAL, analysis_task_id TEXT NOT NULL REFERENCES task(id) ON DELETE RESTRICT, version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, reviewed_at INTEGER);
CREATE TABLE IF NOT EXISTS source_evidence (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT, chapter_version INTEGER NOT NULL, start_offset INTEGER NOT NULL CHECK(start_offset >= 0), end_offset INTEGER NOT NULL CHECK(end_offset >= start_offset), excerpt TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('valid','stale','missing')), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chapter_summary (id TEXT PRIMARY KEY, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT, chapter_version INTEGER NOT NULL, summary TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('current','stale')), analysis_task_id TEXT NOT NULL REFERENCES task(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS book_synopsis (id TEXT PRIMARY KEY, summary TEXT NOT NULL, source_versions_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('current','stale')), analysis_task_id TEXT NOT NULL REFERENCES task(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content_chunk (id TEXT PRIMARY KEY, source_type TEXT NOT NULL CHECK(source_type = 'chapter'), source_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE CASCADE, chapter_id TEXT REFERENCES chapter(id) ON DELETE CASCADE, chapter_version INTEGER, chunk_kind TEXT NOT NULL CHECK(chunk_kind IN ('temporary','semantic')), start_offset INTEGER CHECK(start_offset >= 0), end_offset INTEGER CHECK(end_offset >= start_offset), content TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('current','stale')), created_at INTEGER NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS content_fts USING fts5(title, content, source_type, tokenize='trigram');
CREATE TABLE IF NOT EXISTS search_rowid (rowid INTEGER PRIMARY KEY, source_type TEXT NOT NULL CHECK(source_type IN ('chapter_chunk','knowledge_entry','creative_rules','style_sample')), source_id TEXT NOT NULL, UNIQUE(source_type, source_id));
CREATE TABLE IF NOT EXISTS vector_index_meta (id INTEGER PRIMARY KEY CHECK(id = 1), embedding_connection_fingerprint TEXT, model TEXT, dimensions INTEGER, state TEXT NOT NULL CHECK(state IN ('missing','building','ready','stale','failed')), processed_count INTEGER NOT NULL DEFAULT 0, total_count INTEGER NOT NULL DEFAULT 0, last_error TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS consistency_issue (id TEXT PRIMARY KEY, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT, chapter_version INTEGER NOT NULL, issue_type TEXT NOT NULL, severity TEXT NOT NULL, description TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 1), state TEXT NOT NULL CHECK(state IN ('open','acknowledged','dismissed','stale')), analysis_task_id TEXT NOT NULL REFERENCES task(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, reviewed_at INTEGER);
CREATE TABLE IF NOT EXISTS literary_report (id TEXT PRIMARY KEY, scope_json TEXT NOT NULL, chapter_versions_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('current','stale')), connection_id TEXT, analysis_task_id TEXT REFERENCES task(id) ON DELETE SET NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS report_section (id TEXT PRIMARY KEY, literary_report_id TEXT NOT NULL REFERENCES literary_report(id) ON DELETE CASCADE, section_type TEXT NOT NULL, content TEXT NOT NULL, conclusion TEXT NOT NULL, position INTEGER NOT NULL, UNIQUE(literary_report_id, section_type));
CREATE TABLE IF NOT EXISTS report_annotation (id TEXT PRIMARY KEY, report_section_id TEXT NOT NULL REFERENCES report_section(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS task_step (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES task(id) ON DELETE CASCADE, chapter_id TEXT REFERENCES chapter(id) ON DELETE SET NULL, chapter_version INTEGER, position INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','running','completed','failed','skipped')), attempt_count INTEGER NOT NULL DEFAULT 0, checkpoint_json TEXT, result_state TEXT CHECK(result_state IN ('current','stale')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(task_id, position));
CREATE TABLE IF NOT EXISTS context_package (id TEXT PRIMARY KEY, messages_json TEXT NOT NULL, token_budget INTEGER NOT NULL, estimated_tokens INTEGER NOT NULL, warnings_json TEXT NOT NULL DEFAULT '[]', target_versions_json TEXT NOT NULL, target_length INTEGER, creativity REAL, configuration_fingerprint TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS context_item (id TEXT PRIMARY KEY, context_package_id TEXT NOT NULL REFERENCES context_package(id) ON DELETE CASCADE, source_type TEXT NOT NULL, source_id TEXT NOT NULL, authority_level INTEGER NOT NULL, selection_reason TEXT NOT NULL, estimated_tokens INTEGER NOT NULL, fixed INTEGER NOT NULL CHECK(fixed IN (0,1)), position INTEGER NOT NULL, UNIQUE(context_package_id, position));
CREATE TABLE IF NOT EXISTS candidate (id TEXT PRIMARY KEY, task_id TEXT REFERENCES task(id) ON DELETE SET NULL, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT, chapter_version INTEGER NOT NULL, start_offset INTEGER, end_offset INTEGER, original_content TEXT NOT NULL, raw_output TEXT NOT NULL DEFAULT '', edited_content TEXT, version INTEGER NOT NULL CHECK(version >= 1), state TEXT NOT NULL CHECK(state IN ('streaming','ready','applied','cancelled','failed','rejected','stale')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS candidate_hunk (id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidate(id) ON DELETE CASCADE, position INTEGER NOT NULL, hunk_type TEXT NOT NULL, original_content TEXT NOT NULL, candidate_content TEXT NOT NULL, selected INTEGER NOT NULL CHECK(selected IN (0,1)), UNIQUE(candidate_id, position));
CREATE TABLE IF NOT EXISTS candidate_apply (id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE REFERENCES candidate(id) ON DELETE RESTRICT, chapter_id TEXT NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT, before_chapter_version INTEGER NOT NULL, after_chapter_version INTEGER NOT NULL, chapter_snapshot_id TEXT NOT NULL REFERENCES chapter_snapshot(id) ON DELETE RESTRICT, final_content_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chat_session (id TEXT PRIMARY KEY, title TEXT NOT NULL, connection_id TEXT, version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chat_message (id TEXT PRIMARY KEY, chat_session_id TEXT NOT NULL REFERENCES chat_session(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('system','user','assistant')), content TEXT NOT NULL, context_package_id TEXT REFERENCES context_package(id) ON DELETE SET NULL, token_count INTEGER, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chat_summary (id TEXT PRIMARY KEY, chat_session_id TEXT NOT NULL REFERENCES chat_session(id) ON DELETE CASCADE, start_message_id TEXT REFERENCES chat_message(id) ON DELETE SET NULL, end_message_id TEXT REFERENCES chat_message(id) ON DELETE SET NULL, content TEXT NOT NULL, author_edited INTEGER NOT NULL DEFAULT 0 CHECK(author_edited IN (0,1)), version INTEGER NOT NULL CHECK(version >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_chapter_snapshot_chapter_id ON chapter_snapshot(chapter_id);
CREATE INDEX IF NOT EXISTS idx_task_step_task_id ON task_step(task_id);
CREATE INDEX IF NOT EXISTS idx_source_evidence_chapter_id ON source_evidence(chapter_id);
CREATE INDEX IF NOT EXISTS idx_content_chunk_source_id ON content_chunk(source_id);
